14|static void max_depth() {
15|    json_t *json;
16|    char *result;
17|
18|    /* A structure nested exactly to the limit must still serialize. */
19|    json = build_nested_array(JSON_PARSER_MAX_DEPTH);
20|    result = json_dumps(json, 0);
21|    if (!result)
22|        fail("json_dumps failed for a structure within the depth limit");
23|    free(result);
