139|static void stream_init(stream_t *stream, get_func get, void *data) {
140|    stream->get = get;
141|    stream->data = data;
142|    stream->buffer[0] = '\0';
143|    stream->buffer_pos = 0;
144|
145|    stream->state = STREAM_STATE_OK;
146|    stream->line = 1;
147|    stream->column = 0;
148|    stream->position = 0;
149|}
