247|#ifndef NDEBUG
248|        char d;
249|#endif
250|        stream_unget(&lex->stream, c);
251|#ifndef NDEBUG
252|        d =
253|#endif
254|            strbuffer_pop(&lex->saved_text);
255|        assert(c == d);
256|    }
