273|/* assumes that str points to 'u' plus at least 4 valid hex digits */
274|static int32_t decode_unicode_escape(const char *str) {
275|    int i;
276|    int32_t value = 0;
277|
278|    assert(str[0] == 'u');
279|
280|    for (i = 1; i <= 4; i++) {
281|        char c = str[i];
282|        value <<= 4;
283|        if (l_isdigit(c))
284|            value += c - '0';
285|        else if (l_islower(c))
286|            value += c - 'a' + 10;
287|        else if (l_isupper(c))
288|            value += c - 'A' + 10;
289|        else
290|            return -1;
