662|static json_t *parse_object(lex_t *lex, size_t flags, json_error_t *error) {
663|    json_t *object = json_object();
664|    if (!object)
665|        return NULL;
666|
667|    lex_scan(lex, error);
668|    if (lex->token == '}')
669|        return object;
670|
671|    while (1) {
672|        char *key;
673|        size_t len;
