675|
676|        if (lex->token != TOKEN_STRING) {
677|            error_set(error, lex, json_error_invalid_syntax, "string or '}' expected");
678|            goto error;
679|        }
680|
681|        key = lex_steal_string(lex, &len);
682|        if (!key)
