1069|    if (stream->pos >= stream->len) {
1070|        stream->pos = 0;
1071|        stream->len = stream->callback(stream->data, MAX_BUF_LEN, stream->arg);
1072|        if (stream->len == 0 || stream->len == (size_t)-1)
1073|            return EOF;
