296|static void lex_scan_string(lex_t *lex, json_error_t *error) {
297|    int c;
298|    const char *p;
299|    char *t;
300|    int i;
301|
302|    lex->value.string.val = NULL;
303|    lex->token = TOKEN_INVALID;
