425|                        break;
426|                    case 'b':
427|                        *t = '\b';
428|                        break;
429|                    case 'f':
430|                        *t = '\f';
431|                        break;
432|                    case 'n':
433|                        *t = '\n';
434|                        break;
435|                    case 'r':
436|                        *t = '\r';
437|                        break;
438|                    case 't':
439|                        *t = '\t';
440|                        break;
441|                    default:
