572|    do
573|        c = lex_get(lex, error);
574|    while (c == ' ' || c == '\t' || c == '\n' || c == '\r');
575|
576|    if (c == STREAM_STATE_EOF) {
577|        lex->token = TOKEN_EOF;
578|        goto out;
579|    }
580|
581|    if (c == STREAM_STATE_ERROR) {
582|        lex->token = TOKEN_INVALID;
583|        goto out;
584|    }
585|
586|    lex_save(lex, c);
587|
588|    if (c == '{' || c == '}' || c == '[' || c == ']' || c == ':' || c == ',')
589|        lex->token = c;
