425|char *json_dumps(const json_t *json, size_t flags) {
426|    strbuffer_t strbuff;
427|    char *result;
428|
429|    if (strbuffer_init(&strbuff))
430|        return NULL;
431|
432|    if (json_dump_callback(json, dump_to_strbuffer, (void *)&strbuff, flags))
433|        result = NULL;
434|    else {
435|        char *new_result;
436|        result = strbuffer_steal_value(&strbuff);
437|        // technically the resizing is not needed.
438|        new_result = jsonp_realloc(result, strbuff.size, strbuff.length + 1);
439|        if (new_result) { // when realloc fails we just use the original pointer
440|            result = new_result;
441|        }
442|    }
443|
444|    strbuffer_close(&strbuff);
445|    return result;
446|}
