451|size_t json_dumpb(const json_t *json, char *buffer, size_t size, size_t flags) {
452|    struct buffer buf = {size, 0, buffer};
453|
454|    if (json_dump_callback(json, dump_to_buffer, (void *)&buf, flags))
455|        return 0;
456|
457|    return buf.used;
458|}
