460|int json_dumpf(const json_t *json, FILE *output, size_t flags) {
461|    return json_dump_callback(json, dump_to_file, (void *)output, flags);
462|}
463|
464|int json_dumpfd(const json_t *json, int output, size_t flags) {
465|    return json_dump_callback(json, dump_to_fd, (void *)&output, flags);
466|}
467|
468|int json_dump_file(const json_t *json, const char *path, size_t flags) {
469|    int result;
470|
471|    FILE *output = fopen(path, "w");
472|    if (!output)
473|        return -1;
474|
475|    result = json_dumpf(json, output, flags);
476|
477|    if (fclose(output) != 0)
478|        return -1;
479|
480|    return result;
481|}
482|
483|int json_dump_callback(const json_t *json, json_dump_callback_t callback, void *data,
484|                       size_t flags) {
485|    int res;
486|    hashtable_t parents_set;
487|
488|    if (!(flags & JSON_ENCODE_ANY)) {
489|        if (!json_is_array(json) && !json_is_object(json))
490|            return -1;
491|    }
492|
493|    if (hashtable_init(&parents_set))
494|        return -1;
495|    res = do_dump(json, flags, 0, &parents_set, callback, data);
496|    hashtable_close(&parents_set);
497|
498|    return res;
499|}

