81|static void read_conf(FILE *conffile) {
82|    char *buffer, *line, *val;
83|    conf.have_hashseed = 0;
84|
85|    buffer = loadfile(conffile);
86|    for (line = strtok(buffer, "\r\n"); line; line = strtok(NULL, "\r\n")) {
87|        val = strchr(line, '=');
88|        if (!val) {
89|            printf("invalid configuration line\n");
90|            break;
91|        }
92|        *val++ = '\0';
93|
94|        if (!strcmp(line, "JSON_INDENT"))
95|            conf.indent = atoi(val);
96|        if (!strcmp(line, "JSON_COMPACT"))
97|            conf.compact = atoi(val);
98|        if (!strcmp(line, "JSON_ENSURE_ASCII"))
99|            conf.ensure_ascii = atoi(val);
100|        if (!strcmp(line, "JSON_PRESERVE_ORDER"))
101|            conf.preserve_order = atoi(val);
102|        if (!strcmp(line, "JSON_SORT_KEYS"))
103|            conf.sort_keys = atoi(val);
104|        if (!strcmp(line, "JSON_REAL_PRECISION"))
105|            conf.precision = atoi(val);
106|        if (!strcmp(line, "STRIP"))
107|            conf.strip = atoi(val);
108|        if (!strcmp(line, "HASHSEED")) {
109|            conf.have_hashseed = 1;
110|            conf.hashseed = atoi(val);
111|        }
112|    }
113|
114|    free(buffer);
115|}

