153|int use_conf(char *test_path) {
154|    int ret;
155|    size_t flags = 0;
156|    char filename[1024], errstr[1024];
157|    char *buffer;
158|    FILE *infile, *conffile;
159|    json_t *json;
160|    json_error_t error;
161|
162|    sprintf(filename, "%s%cinput", test_path, dir_sep);
163|    if (!(infile = fopen(filename, "rb"))) {
164|        fprintf(stderr, "Could not open \"%s\"\n", filename);
165|        return 2;
166|    }
167|
168|    sprintf(filename, "%s%cenv", test_path, dir_sep);
169|    conffile = fopen(filename, "rb");
170|    if (conffile) {
171|        read_conf(conffile);
172|        fclose(conffile);
173|    }
174|
175|    if (conf.indent < 0 || conf.indent > 31) {
176|        fprintf(stderr, "invalid value for JSON_INDENT: %d\n", conf.indent);
177|        fclose(infile);
178|        return 2;
179|    }
180|    if (conf.indent)
181|        flags |= JSON_INDENT(conf.indent);
182|
183|    if (conf.compact)
184|        flags |= JSON_COMPACT;
185|
186|    if (conf.ensure_ascii)
187|        flags |= JSON_ENSURE_ASCII;
188|
189|    if (conf.preserve_order)
190|        flags |= JSON_PRESERVE_ORDER;
191|
192|    if (conf.sort_keys)
193|        flags |= JSON_SORT_KEYS;
194|
195|    if (conf.precision < 0 || conf.precision > 31) {
196|        fprintf(stderr, "invalid value for JSON_REAL_PRECISION: %d\n", conf.precision);
197|        fclose(infile);
198|        return 2;
199|    }
200|    if (conf.precision)
201|        flags |= JSON_REAL_PRECISION(conf.precision);
202|
203|    if (conf.have_hashseed)
204|        json_object_seed(conf.hashseed);
205|
206|    if (conf.strip) {
207|        /* Load to memory, strip leading and trailing whitespace */
208|        buffer = loadfile(infile);
209|        json = json_loads(strip(buffer), 0, &error);
210|        free(buffer);
211|    } else {
212|        json = json_loadf(infile, 0, &error);
213|    }
214|
215|    fclose(infile);
216|
217|    if (!json) {
218|        sprintf(errstr, "%d %d %d\n%s\n", error.line, error.column, error.position,
219|                error.text);
220|
221|        ret = cmpfile(errstr, test_path, "error");
222|        return ret;
223|    }
224|
225|    buffer = json_dumps(json, flags);
226|    ret = cmpfile(buffer, test_path, "output");
227|    free(buffer);
228|    json_decref(json);
229|
230|    return ret;
231|}

