554|int json_array_insert_new(json_t *json, size_t index, json_t *value) {
555|    json_array_t *array;
556|
557|    if (!value)
558|        return -1;
559|
560|    if (!json_is_array(json) || json == value) {
561|        json_decref(value);
562|        return -1;
563|    }
564|    array = json_to_array(json);
565|
566|    if (index > array->entries) {
567|        json_decref(value);
568|        return -1;
569|    }
570|
571|    if (!json_array_grow(array, 1)) {
572|        json_decref(value);
573|        return -1;
574|    }
575|    if (index != array->entries)
576|        array_move(array, index + 1, index, array->entries - index);
577|
578|    array->table[index] = value;
579|    array->entries++;
580|
581|    return 0;
582|}

