584|int json_array_remove(json_t *json, size_t index) {
585|    json_array_t *array;
586|
587|    if (!json_is_array(json))
588|        return -1;
589|    array = json_to_array(json);
590|
591|    if (index >= array->entries)
592|        return -1;
593|
594|    json_decref(array->table[index]);
595|
596|    /* If we're removing the last element, nothing has to be moved */
597|    if (index < array->entries - 1)
598|        array_move(array, index, index + 1, array->entries - index - 1);
599|
600|    array->entries--;
601|
602|    return 0;
603|}

